    for (let i = 0; i < parts.length; i++) {
      const p = r.parts[i];
      if (p.startsWith(":")) params[p.slice(1)] = decodeURIComponent(parts[i]);
      else if (p !== parts[i]) {
        ok = false;
        break;
      }
    }
    if (!ok) continue;
